        for index, scheduled in enumerate(cases):
            options = dict(scheduled)
            arm, block = options.pop("arm"), options.pop("block")
            result = None
            started = None
            try:
                if source_identity(roots[arm]) != sources[arm] or harness_identity() != harness:
