                  'inputSchema': {'type': 'object', 'properties': {'text': {'type': 'string'}}},
                  'outputSchema': {'type': 'object'}, 'annotations': {'readOnlyHint': True}}
                 for i in range(size)]}
    elif method == 'tools/call':
        start_cpu = time.process_time_ns()
